
(function(){
const root=document.getElementById('ra-shop'), screen=root.querySelector('#screen'), dialog=root.querySelector('#dialog');
const products=[{id:1,name:'Homestyle mango pickle',cat:'Pickles',unit:'250 g · Traditional recipe',price:149,stock:18,emoji:'🫙',offer:'Local favourite'},{id:2,name:'Premium sona masoori',cat:'Groceries',unit:'5 kg · Everyday essentials',price:329,stock:24,emoji:'🌾',offer:'Everyday value'},{id:3,name:'Everyday storage set',cat:'Home & plastic',unit:'Set of 3 · With lids',price:199,stock:8,emoji:'🥣',offer:'Popular pick'},{id:4,name:'Cotton everyday tee',cat:'Clothing',unit:'Olive · Sizes M / L / XL',price:399,stock:12,emoji:'👕',offer:'New arrival'},{id:5,name:'Groundnut oil',cat:'Groceries',unit:'1 litre · Cooking essential',price:189,stock:0,emoji:'🍶',offer:'Restocking soon'},{id:6,name:'Lemon pickle',cat:'Pickles',unit:'250 g · Tangy & traditional',price:129,stock:15,emoji:'🍋',offer:'Kitchen favourite'},{id:7,name:'Multipurpose basket',cat:'Home & plastic',unit:'Medium · Household storage',price:119,stock:9,emoji:'🧺',offer:'Organise your home'},{id:8,name:'Cotton kurta',cat:'Clothing',unit:'Blue · Sizes M / L / XL',price:649,stock:6,emoji:'👗',offer:'Comfort, every day'}];
let billOffer={enabled:true,name:'Launch offer · 5% off',percent:5,minimumPaise:0,capPaise:0,stack:false,start:'',end:''};
let branding={name:'Racharla Mart',tagline:'Your neighbourhood, delivered',description:'Pantry favourites, home essentials and everyday style. All from your local store.',logo:'',phone:'',email:'',address:'',hours:'',about:'Your local store for everyday essentials and more.'};
let categories=['Groceries','Pickles','Home & plastic','Clothing','Snacks','Food','Homemade Food'].map(name=>({name,enabled:true}));
let serviceNotice={enabled:false,reason:'Weather delay',message:'Deliveries may take longer due to bad weather. Thank you for your patience.',extraMinutes:20,pauseOrders:false,expiresAt:''};
let slides=[{id:'slide-local',enabled:true,title:'Everyday favourites. Local convenience.',body:'Explore the shelves and see today’s offers at checkout.',button:'Shop all',target:'',image:''},{id:'slide-snacks',enabled:true,title:'A little crunch for your break.',body:'A dedicated place for snacks and teatime favourites.',button:'Explore snacks',target:'Snacks',image:''},{id:'slide-home',enabled:true,title:'Made at home. Made with care.',body:'Our future home-food collection starts here. Sample items are not available to order yet.',button:'View collection',target:'Homemade Food',image:''}];
let resetting=false;
let videos=[],contentTab='brand',slideIndex=0,slidePaused=false,slideTimer=null,contentVersion=1;
let reviewedCheckout='';
let storePin=null,customerPin=null,deliveryEnabled=true,serviceCity='',allowedPincodes=[];
let policy={version:'v1',freeMinutes:10,demoFeesEnabled:false,afterDispatchFee:30,maxFee:50};
let view='shop',section='overview',category='All',query='',cart={},distance=2,free=false,radius=5,freeKm=1,rate=10,storeMode='open',message='We’re updating the store. Please visit again soon.',banner='A little local. A lot to love.',orders=[{id:'RM-1042',total:487,status:'Preparing',items:'Mango pickle × 2 · Groundnut oil × 1',driver:'Unassigned',refund:'None'}];
const money=n=>'₹'+n.toLocaleString('en-IN',{maximumFractionDigits:2}), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const entries=()=>InventoryRules.rows(products,cart);

function notify(s){root.querySelector('#feedback').hidden=false;root.querySelector('#feedback').textContent=s;}
function modal(html){clearMap();dialog.hidden=false;dialog.innerHTML='<div class="row between"><span class="eyebrow">'+esc(branding.name)+' · Preview</span><button data-act="close">Close ×</button></div>'+html;}
function go(v){clearMap();view=v;dialog.hidden=true;render();}
function render(){stopSlides();syncBrand();saveState();root.querySelector('#bag-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);root.querySelectorAll('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='shop')shop();if(view==='cart')checkout();if(view==='orders')orderPage();if(view==='admin')admin();if(view==='delivery')delivery();}
function shop(){if(storeMode!=='open'){screen.innerHTML='<div class="box empty"><span class="eyebrow">'+(storeMode==='maintenance'?'Store update':'Store temporarily closed')+'</span><h1>We’ll be back.</h1><p>'+esc(message)+'</p><button data-view="orders">View existing orders</button> <button data-act="help">Contact support</button></div>';return;}
screen.innerHTML=(CommerceRules.active(billOffer)?'<div class="launch-strip"><b>'+esc(billOffer.name)+'</b><span>'+billOffer.percent+'% off eligible items'+(billOffer.minimumPaise?' · Minimum '+money(billOffer.minimumPaise/100):'')+(billOffer.capPaise?' · Save up to '+money(billOffer.capPaise/100):'')+' · '+(billOffer.stack?'Combines with product offers':'Best offer applied')+'</span></div>':'')+'<section class="hero"><div class="hero-copy"><span class="eyebrow">Your everyday, made easier</span><h1>'+esc(banner)+'</h1><p>Pantry favourites, home essentials and everyday style. All from your local store.</p><button class="strong" data-act="browse">Explore the shelves →</button><p><small>Delivery within '+radius+' km · '+(free?'Free delivery offer':'First '+freeKm+' km free')+'</small></p></div><div class="hero-art" aria-label="Illustrative product packaging"><div class="pack"><i>🫙</i><b>Homestyle</b><small> Pickles</small></div><div class="pack"><i>🌾</i><b>Everyday</b><small> Staples</small></div><div class="pack"><i>🧺</i><b>Happy home</b><small> Essentials</small></div></div></section><div class="row between"><div><h2>Find your everyday favourites</h2><span class="muted">One basket. One local store.</span></div><input class="search" id="search" aria-label="Search products" placeholder="Search rice, pickle, clothing…" value="'+esc(query)+'"></div>'+categoryWidgets()+'<div class="products" id="products"></div>';productGrid();decorateShop();}

function admin(){screen.innerHTML='<div class="row between"><div><span class="eyebrow">Store workspace</span><h2>You’re in control.</h2></div><span class="status">'+esc(storeMode==='open'?'● Store accepting orders':storeMode)+'</span></div><nav class="subnav section">'+['overview','products','inventory','offers','orders','delivery','delays','content','cancellations','settings','review'].map(s=>'<button data-section="'+s+'" class="'+(section===s?'active':'')+'">'+s[0].toUpperCase()+s.slice(1)+'</button>').join('')+'</nav><div id="admin-content"></div>';const a=screen.querySelector('#admin-content');
if(section==='overview')a.innerHTML=analytics();
if(section==='inventory')a.innerHTML=inventoryDashboard();
if(section==='cancellations')a.innerHTML=cancellationSettings();
if(section==='content')a.innerHTML=contentSettings();
if(section==='delays')a.innerHTML=delaySettings();
if(section==='offers'){a.innerHTML=offerSettings();offerExample();}
if(section==='products')a.innerHTML=variantInventoryPanel();
if(section==='review')a.innerHTML=reviewPanel();
if(section==='orders')a.innerHTML=orders.map(o=>'<div class="box section"><div class="row between"><h3>'+o.id+'</h3><b>'+money(o.total)+'</b></div><p>'+esc(o.items)+'</p><div class="editgrid"><label><span>Order status</span><select data-status="'+o.id+'">'+['Preparing','Ready for pickup','Out for delivery','Delivered','Failed delivery','Cancelled'].map(s=>'<option '+(s===o.status?'selected':'')+'>'+s+'</option>').join('')+'</select></label><label><span>Assign rider</span><select data-driver="'+o.id+'">'+['Unassigned','Ravi · Demo rider','Lakshmi · Demo rider'].map(s=>'<option '+(s===o.driver?'selected':'')+'>'+s+'</option>').join('')+'</select></label><div><label><span>Refund · '+esc(o.refund)+'</span></label><button data-process="'+o.id+'">Review refund</button> <button data-cancel-admin="'+o.id+'">Cancel order</button> <button data-invoice="'+o.id+'">Receipt / print</button> <button data-history="'+o.id+'">History & emails</button></div></div></div>').join('');
if(section==='delivery')a.innerHTML=deliverySettings();
if(section==='settings')a.innerHTML='<div class="columns"><div class="box"><h3>Store availability</h3><label><span>Store mode</span><select id="store-mode"><option value="open" '+(storeMode==='open'?'selected':'')+'>Open · Accept orders</option><option value="closed" '+(storeMode==='closed'?'selected':'')+'>Closed · Pause new orders</option><option value="maintenance" '+(storeMode==='maintenance'?'selected':'')+'>Maintenance · Show update message</option></select></label><label><span>Customer message</span><textarea id="closed-message">'+esc(message)+'</textarea></label><label><span>Homepage headline / offer</span><input id="banner" value="'+esc(banner)+'"></label><button class="strong" data-act="save-settings">Save & preview</button></div><div class="box"><h3>Launch connections</h3><div class="listrow">Supabase <span class="tag">Not connected</span></div><div class="listrow">Google + email sign-in <span class="tag">Preview</span></div><div class="listrow">Razorpay payments & refunds <span class="tag">Not connected</span></div><div class="listrow">Maps & delivery location <span class="tag">Preview · road routing pending</span></div><div class="listrow">SEO, PWA & custom domain <span class="tag">Build phase</span></div><small>Admin access here is a design preview, not authentication. Changes are saved only in this browser; cross-device sync requires Supabase.</small></div></div>';
}
root.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;productGrid();}if(e.target.id==='distance'){distance=Number(e.target.value);checkout();}});
root.addEventListener('change',e=>{if(e.target.dataset.status){const o=orders.find(o=>o.id===e.target.dataset.status);try{StoreRules.transition(o,e.target.value,'Admin');notify('Status updated. Customer timeline and preview notification log updated.');}catch(err){notify(err.message);}render();}if(e.target.dataset.driver){const o=orders.find(o=>o.id===e.target.dataset.driver);o.driver=e.target.value;StoreRules.event(o,'Admin','Rider assigned: '+o.driver);saveState();notify('Demo rider assignment updated.');}});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
if(d.foodDetails){const p=products.find(p=>p.id===+d.foodDetails);return modal('<h2>'+esc(p.name)+'</h2><p style="white-space:pre-wrap">'+esc(p.foodNotes)+'</p>');}if(d.view)return go(d.view);if(d.section){section=d.section;return go('admin');}if(d.cat){category=d.cat;return shop();}
if(d.add){try{const p=products.find(p=>p.id===+d.add);if(!p||!categoryVisible(p.cat))throw Error('Product unavailable.');const v=chosenVariant(p);InventoryRules.add(products,cart,p.id,v.id);render();notify(p.name+' · '+v.label+' added to your bag.');}catch(err){notify(err.message);}return;}
if(d.qty){try{const {productId,variantId}=InventoryRules.decode(d.qty);InventoryRules.add(products,cart,productId,variantId,Number(d.delta));render();}catch(err){notify(err.message);}return;}
if(d.edit)return editProduct(products.find(p=>p.id===+d.edit));
if(d.saveProduct){saveProduct(products.find(p=>p.id===+d.saveProduct),b);return;}

if(d.invoice)return invoice(orders.find(o=>o.id===d.invoice));
if(d.refund){const o=orders.find(o=>o.id===d.refund);if(o.refund!=='None')return notify('A refund request already exists. Check your order timeline.');o.refund='Requested';StoreRules.event(o,'Customer','Refund review requested');StoreRules.queueEmail(o,'Refund request received');render();return notify('Refund review requested. No money moved.');}
if(d.process){const o=orders.find(o=>o.id===d.process);return modal('<h2>Review refund · '+o.id+'</h2><p>Order total '+money(o.total)+'</p><label><span>Reason</span><select><option>Item unavailable</option><option>Failed delivery</option><option>Return approved</option></select></label><label><span>Refund amount (₹)</span><input id="refund-amount" type="number" min="1" max="'+o.total+'" value="'+o.total+'"></label><button class="strong" data-approve="'+o.id+'">Simulate refund submission</button><p><small>Live refunds need payment verification and Razorpay confirmation. Submission is not completion.</small></p>');}
if(d.approve){const o=orders.find(o=>o.id===d.approve),amount=+root.querySelector('#refund-amount').value;try{StoreRules.refund(o,StoreRules.minor(amount),'Admin','Admin-approved refund review');dialog.hidden=true;render();notify('Refund request recorded as pending. No money moved.');}catch(err){notify(err.message);}return;}
if(d.delivered||d.failed){const o=orders.find(o=>o.id===(d.delivered||d.failed));if(d.failed){if(o.status!=='Out for delivery')return notify('Only dispatched orders can have a failed delivery.');return modal('<h2>Report delivery failure</h2><label><span>Reason</span><select id="failure-reason"><option>Customer unavailable</option><option>Address could not be located</option><option>Vehicle or rider issue</option><option>Goods damaged in transit</option></select></label><button data-confirm-failure="'+o.id+'">Record failure for admin review</button>');}try{StoreRules.transition(o,'Delivered','Assigned rider');render();}catch(err){notify(err.message);}return;}
if(d.info==='Install app'){window.StoreInstall().then(notify).catch(()=>notify('Installation is unavailable in this browser.'));return;}if(d.info==='About')return modal('<h2>About '+esc(branding.name)+'</h2><p>'+esc(branding.about)+'</p>');if(d.info==='Contact')return modal('<h2>Contact '+esc(branding.name)+'</h2><p>'+esc(branding.phone||'Phone not set')+'</p><p>'+esc(branding.email||'Email not set')+'</p><p>'+esc(branding.address||'Address not set')+'</p><p>'+esc(branding.hours)+'</p>');if(d.info){const info={'About':'A local store for groceries, homestyle foods, home essentials and clothing. Brand and business details are placeholders.','Contact':'Customer phone, WhatsApp, email, store address and opening hours will appear here.','Privacy':'Preview: chosen addresses and coordinates are stored only in this browser. Opening maps requests tiles from OpenStreetMap and loads Leaflet from unpkg. Uploaded content stays in this browser; external images load from their hosting site. Pressing Play connects to YouTube or Vimeo. Device location is requested only after you press Use my location. Reset demo clears saved preview data. The final policy must cover backend storage, payments, retention and deletion.','Terms':'Preview placeholder. Final terms will cover ordering, service areas, pricing, cancellations and seller details.','Returns & refunds':'Refund eligibility and return windows will vary by product category. Approved refunds show Requested → Processing → Completed after provider confirmation.','Install app':'Planned PWA: installable on supported phones and desktops. Offline browsing must not accept orders or promise live stock.'};return modal('<h2>'+esc(d.info)+'</h2><p>'+info[d.info]+'</p>');}
switch(d.act){case 'close':clearMap();dialog.hidden=true;break;case 'browse':root.querySelector('#search').focus();break;case 'location':locationModal('customer');break;case 'login':modal('<h2>Welcome to your local store</h2><button class="wide" data-act="auth-demo">Continue with Google</button><p class="muted">or use your email</p><label><span>Email</span><input type="email" placeholder="you@example.com" autocomplete="off"></label><label><span>Password</span><input type="password" placeholder="Demo only — don’t enter a real password" autocomplete="off"></label><button class="strong wide" data-act="auth-demo">Sign in / create account</button>');break;case 'auth-demo':notify('Authentication is a design preview. Google and email login will connect through Supabase.');dialog.hidden=true;break;case 'help':modal('<h2>How can we help?</h2><p>Ask about products, your order or delivery.</p><label><span>Your question</span><input placeholder="When will my order arrive?"></label><div class="row"><button data-act="chat-demo">Ask assistant</button><button data-act="human-demo">Talk to store team</button></div><small>AI answers and human handoff are preview controls.</small>');break;case 'chat-demo':notify('Preview reply: delivery updates will appear under My orders. For an order problem, contact the store team. This is a scripted reply, not AI.');break;case 'human-demo':notify('Human support handoff preview. No message was sent.');break;
case 'place':placeOrder();break;
case 'reset':if(confirm('Reset all local sample orders, products and settings?')){resetting=true;localStorage.removeItem('racharla-preview-v2');location.reload();}break;
case 'save-delivery':{const r=+root.querySelector('#radius').value,f=+root.querySelector('#free-km').value,t=+root.querySelector('#rate').value;if(r<=0||r>50||f<0||t<0)return notify('Check your delivery values.');radius=r;freeKm=f;rate=t;free=root.querySelector('#free').checked;notify('Delivery rules updated for this preview. Check the bag to see charges.');break;}
case 'save-settings':storeMode=root.querySelector('#store-mode').value;message=root.querySelector('#closed-message').value;banner=root.querySelector('#banner').value;go('shop');notify('Store settings updated in the preview. Admin remains accessible.');break;
case 'new':{const p={id:Math.max(...products.map(p=>p.id))+1,name:'New product',cat:categories[0].name,unit:'Edit product details',price:100,stock:0,emoji:'📦',offer:'New'};InventoryRules.migrate(p);products.push(p);admin();notify('Draft product added with zero stock. Choose Edit to set name, price, image and stock.');break;}
}});

function normalizeOrders(){for(const o of orders){o.createdAt ||= new Date(Date.now()-3600000).toISOString();o.policy ||= {...policy};o.history ||= [{actor:'System',message:'Sample order created',at:o.createdAt}];o.notifications ||= [];o.pendingRefundPaise ||= 0;o.refundedPaise ||= 0;}}
function saveState(){if(resetting)return;try{localStorage.setItem('racharla-preview-v2',JSON.stringify({products:products.map(p=>({...p,image:p.image?.startsWith('blob:')?undefined:p.image})),orders,cart,distance,free,radius,freeKm,rate,storeMode,message,banner,policy,billOffer,storePin,customerPin,deliveryEnabled,serviceCity,allowedPincodes,branding,categories,serviceNotice,slides,videos,slidePaused,contentVersion,inventoryEvents}));}catch{notify('Browser storage is full or unavailable. Changes work only until reload; remove large images before leaving.');}}
function restoreState(){try{const saved=JSON.parse(localStorage.getItem('racharla-preview-v2'));if(saved){products.splice(0,products.length,...saved.products);orders=saved.orders;cart=saved.cart;distance=saved.distance;free=saved.free;radius=saved.radius;freeKm=saved.freeKm;rate=saved.rate;storeMode=saved.storeMode;message=saved.message;banner=saved.banner;policy=saved.policy;billOffer=saved.billOffer||billOffer;storePin=saved.storePin||null;customerPin=saved.customerPin||null;deliveryEnabled=saved.deliveryEnabled??true;serviceCity=saved.serviceCity||'';allowedPincodes=saved.allowedPincodes||[];branding={...branding,...saved.branding};categories=saved.categories||categories;serviceNotice={...serviceNotice,...saved.serviceNotice};slides=saved.slides||slides;videos=saved.videos||[];slidePaused=saved.slidePaused??false;contentVersion=saved.contentVersion||1;inventoryEvents=saved.inventoryEvents||[];}}catch{localStorage.removeItem('racharla-preview-v2');}normalizeOrders();}
const stamp=at=>new Date(at).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'});
function orderPage(){screen.innerHTML='<h2>Your orders</h2><p class="muted">Order history, delivery updates and refund breakdowns.</p>'+orders.map(o=>'<article class="box section"><div class="row between"><h3>'+o.id+'</h3><span class="status">'+esc(o.status)+'</span><b>'+money(o.total)+'</b></div><p>'+esc(o.items)+'</p><small>Placed '+stamp(o.createdAt)+' · '+esc(o.driver)+'</small><div class="steps">'+['Preparing','Ready for pickup','Out for delivery','Delivered'].map(s=>'<span>'+(s===o.status?'● ':'')+s+'</span>').join('')+'</div>'+(o.cancellation?'<div class="policy-summary"><b>Cancellation summary</b><div class="sum"><span>Reason</span><span>'+esc(o.cancellation.reason)+'</span></div><div class="sum"><span>Cancellation fee</span><b>'+money(o.cancellation.chargePaise/100)+'</b></div><div class="sum"><span>Refund due</span><b>'+money(o.cancellation.refundPaise/100)+'</b></div></div>':'')+'<p>Refund: '+esc(o.refund)+'</p><div class="row"><button data-invoice="'+o.id+'">Invoice</button><button data-history="'+o.id+'">Timeline & emails</button><button data-resend="'+o.id+'">Resend order email</button>'+(!['Delivered','Cancelled'].includes(o.status)?'<button data-cancel-customer="'+o.id+'">Cancel order</button>':'')+(o.status!=='Cancelled'?'<button data-refund="'+o.id+'">Request refund review</button>':'')+'</div></article>').join('');}
function cancellationSettings(){return '<div class="cancel-grid"><div class="box"><h3>Cancellation policy</h3><p class="muted">New rules apply only to new orders.</p><label><span>Free cancellation window (minutes)</span><input id="policy-minutes" type="number" min="1" max="120" value="'+policy.freeMinutes+'"></label><label><span>After-dispatch fee (₹) · simulation only</span><input id="policy-fee" type="number" min="0" max="500" value="'+policy.afterDispatchFee+'"></label><label><span>Maximum deduction (₹)</span><input id="policy-max" type="number" min="0" max="500" value="'+policy.maxFee+'"></label><label><input id="policy-enabled" type="checkbox" '+(policy.demoFeesEnabled?'checked':'')+'> Enable fee simulation for new demo orders</label><div class="notice">Live deductions remain disabled. Legal review and reciprocal business-cancellation obligations must be resolved before launch.</div><button class="strong" data-save-policy="1">Save policy version</button></div><div class="box"><h3>Refund review queue</h3>'+orders.filter(o=>o.refund!=='None').map(o=>'<div class="listrow"><div class="grow"><b>'+o.id+'</b><br><small>'+esc(o.refund)+'</small></div><button data-history="'+o.id+'">Review</button></div>').join('')+'<h3 class="section">Policy safeguards</h3><p>Store-fault cancellations: no customer deduction.</p><p>Grace period starts at order confirmation. Dispatch time is recorded.</p><p>Rider failure is reviewed; it never triggers an automatic fee.</p><p>Refund completion requires payment-provider confirmation.</p><small>Active version: '+esc(policy.version)+'</small></div></div>';}
function historyModal(o){modal('<h2>'+o.id+' · Timeline</h2>'+o.history.map(h=>'<div class="log"><b>'+esc(h.message)+'</b><small>'+esc(h.actor)+' · '+stamp(h.at)+'</small></div>').join('')+'<h3 class="section">Email notifications</h3>'+(o.notifications.length?o.notifications.map(n=>'<div class="log"><b>'+esc(n.subject)+'</b><small>'+esc(n.state)+' · '+stamp(n.at)+'</small></div>').join(''):'<p>No notification records yet.</p>')+'<p><small>These are preview records. Resend is not connected and no emails are sent.</small></p>');}
let currentQuote=null;
function cancelModal(id,who){const o=orders.find(o=>o.id===id);if(['Cancelled','Delivered'].includes(o.status))return notify('This order cannot be cancelled. Delivered orders use return review.');modal('<h2>Cancel '+o.id+'</h2><label><span>Cancellation reason</span><select id="cancel-reason">'+(who==='admin'?['Stock unavailable','Technical issue','Store unable to deliver']:['Changed my mind','Ordered by mistake']).map(s=>'<option>'+s+'</option>').join('')+'</select></label><p class="muted">Policy '+esc(o.policy.version)+' · Paid '+money(o.total)+'</p><button class="strong" data-quote="'+id+'" data-who="'+who+'">Review fee & refund</button><p><small>No cancellation is applied until you review the breakdown and confirm.</small></p>');}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;try{
if(d.history)historyModal(orders.find(o=>o.id===d.history));
if(d.resend){const o=orders.find(o=>o.id===d.resend);StoreRules.queueEmail(o,'Order update: '+o.status,Date.now(),true);notify('Resend simulated. Email is not connected. A 60-second cooldown applies.');}
if(d.cancelCustomer||d.cancelAdmin)cancelModal(d.cancelCustomer||d.cancelAdmin,d.cancelCustomer?'customer':'admin');
if(d.quote){const o=orders.find(o=>o.id===d.quote),reason=root.querySelector('#cancel-reason').value;currentQuote={id:o.id,...StoreRules.quote(o,d.who,reason)};const q=currentQuote;modal('<h2>Review cancellation</h2><p>'+o.id+' · '+esc(reason)+'</p><div class="sum"><span>Amount paid</span><b>'+money(o.total)+'</b></div><div class="sum"><span>Cancellation deduction</span><b>'+money(q.chargePaise/100)+'</b></div><div class="sum"><b>Refund to original payment method</b><b>'+money(q.refundPaise/100)+'</b></div><p class="notice">'+(q.chargePaise?'Demo fee applies after the grace period and dispatch, including free-delivery promotions.':'No cancellation deduction applies.')+'</p><div class="row"><button data-confirm-cancel="1" class="strong">Confirm demo cancellation</button><button data-act="close">Keep my order</button></div><small>Refund remains pending. No real payment is processed.</small>');}
if(d.confirmCancel){if(!currentQuote)throw Error('Review your cancellation first.');const o=orders.find(o=>o.id===currentQuote.id);StoreRules.cancel(o,currentQuote,currentQuote.who==='admin'?'Admin':'Customer');currentQuote=null;dialog.hidden=true;render();notify('Cancellation recorded. Refund is pending; email recorded as preview only. Stock requires inspection before restocking.');}
if(d.confirmFailure){const o=orders.find(o=>o.id===d.confirmFailure);if(o.status!=='Out for delivery')throw Error('Order is no longer out for delivery.');const reason=root.querySelector('#failure-reason').value;o.status='Failed delivery';StoreRules.event(o,'Assigned rider','Delivery failed: '+reason);StoreRules.queueEmail(o,'Delivery issue — admin review required');dialog.hidden=true;render();notify('Failure recorded for admin review. No cancellation fee or refund was applied automatically.');}
if(d.savePolicy){const mins=+root.querySelector('#policy-minutes').value,fee=+root.querySelector('#policy-fee').value,max=+root.querySelector('#policy-max').value;if(!Number.isInteger(mins)||mins<1||mins>120||!Number.isFinite(fee)||fee<0||fee>500||!Number.isFinite(max)||max<0||max>500)throw Error('Use 1–120 whole minutes and fees between ₹0 and ₹500.');policy={version:'v'+Date.now(),freeMinutes:mins,afterDispatchFee:fee,maxFee:max,demoFeesEnabled:root.querySelector('#policy-enabled').checked};admin();notify('New policy saved. Existing orders keep their original policy.');}
}catch(err){notify(err.message);}queueMicrotask(saveState);});
root.addEventListener('change',()=>queueMicrotask(saveState));
window.addEventListener('offline',()=>notify('Offline. Ordering is paused until you reconnect.'));
function deliveryConfig(){return {enabled:deliveryEnabled&&!(activeNotice()&&serviceNotice.pauseOrders),store:storePin,radius,freeKm,extraKmPaise:Math.round(rate*100),free,pincodes:allowedPincodes};}
function deliveryQuote(){return CommerceRules.delivery(deliveryConfig(),customerPin);}
function pricing(){const d=deliveryQuote();return CommerceRules.quote(entries().map(e=>({id:e.key,productId:e.p.id,name:e.p.name,category:e.p.cat,quantity:e.qty,size:e.size,variantId:e.v?.id,pricePaise:Math.round(e.price*100),offer:e.p.discount})),billOffer,d.eligible?d.feePaise:0);}
function sale(p){const q=CommerceRules.quote([{pricePaise:Math.round(p.price*100),quantity:1,offer:p.discount}],{});return q.total/100;}
function priceMarkup(p){const value=sale(p);return '<span class="price">'+money(value)+'</span>'+(value<p.price?' <del class="muted">'+money(p.price)+'</del><small class="saving">Save '+money(p.price-value)+'</small>':'');}
function scheduleStatus(o){if(!o?.enabled)return 'Off';if(o.start&&Date.parse(o.start)>Date.now())return 'Scheduled';if(o.end&&Date.parse(o.end)<=Date.now())return 'Expired';return 'Active';}
function localTime(iso){if(!iso)return '';const d=new Date(iso);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function scheduleValue(id){const raw=root.querySelector('#'+id).value;if(!raw)return '';const d=new Date(raw);if(Number.isNaN(+d))throw Error('Choose valid offer dates.');return d.toISOString();}
function validDates(start,end){if(start&&end&&Date.parse(end)<=Date.parse(start))throw Error('Offer end must be later than its start.');}
function checkout(){const list=entries(),d=deliveryQuote(),q=pricing();reviewedCheckout=JSON.stringify({q,d,policy});
screen.innerHTML='<div class="row between"><h2>Your shopping bag</h2><button data-view="shop">Continue shopping</button></div>'+(list.length?(blockedCart()?'<p class="notice">An item or pack size is unavailable or has insufficient stock. Reduce its quantity or remove it before ordering.</p>':'')+'<div class="columns section"><div><div class="box">'+list.map((e,i)=>'<div class="listrow"><span class="tinyart">'+e.p.emoji+'</span><div class="grow"><b>'+esc(e.p.name)+'</b><br><small>'+esc(e.size||e.p.unit)+'</small></div><button aria-label="Remove one '+esc(e.p.name)+'" data-qty="'+e.key+'" data-delta="-1">−</button><span>'+e.qty+'</span><button aria-label="Add one '+esc(e.p.name)+'" data-qty="'+e.key+'" data-delta="1">+</button><div><b>'+money(q.lines[i].net/100)+'</b>'+(q.lines[i].net<q.lines[i].gross?'<br><del class="muted">'+money(q.lines[i].gross/100)+'</del>':'')+'</div></div>').join('')+'</div><div class="box section"><h3>Where should we deliver?</h3><p>'+esc(customerPin?.address||'Select your address and delivery pin.')+'</p><button data-act="location">⌖ Choose / change delivery pin</button><div class="notice">'+esc(d.reason)+(Number.isFinite(d.distance)?' · '+d.distance.toFixed(2)+' km straight-line distance':'')+'</div><small>Map radius uses straight-line distance, not road length. '+(allowedPincodes.length?'Selected PIN code must also be allowed.':'')+'</small></div></div><aside class="box"><h3>Order summary</h3><div class="sum"><span>Items before offers</span><b>'+money(q.subtotal/100)+'</b></div><div class="sum"><span>Product discounts</span><b>−'+money(q.productDiscount/100)+'</b></div><div class="sum"><span>'+esc(billOffer.name)+'</span><b>−'+money(q.billDiscount/100)+'</b></div><div class="sum"><span>Delivery</span><b>'+(d.eligible?money(q.deliveryPaise/100):'Select location')+'</b></div><p class="muted">'+(billOffer.stack?'Bill offer applies after product discounts.':'Best of product offers or the bill offer; discounts do not stack.')+'</p>'+(billOffer.minimumPaise&&!q.billEligible?'<small>Bill offer minimum: '+money(billOffer.minimumPaise/100)+' in eligible items.</small>':'')+'<hr><div class="sum"><b>'+(d.eligible?'Total payable':'Items total · delivery pending')+'</b><b>'+money(q.total/100)+'</b></div><div class="saving">You save '+money(q.savings/100)+'</div><div class="policy-summary">Free cancellation within '+policy.freeMinutes+' minutes. '+(policy.demoFeesEnabled?'Demo fee after dispatch and grace period: up to '+money(Math.min(policy.afterDispatchFee,policy.maxFee))+', including free-delivery offers.':'Cancellation deductions are disabled.')+'</div><button class="strong wide" data-act="place" '+(!d.eligible||blockedCart()||storeMode!=='open'?'disabled':'')+'>Place demo order →</button><p><small>Current offers are rechecked at order placement. No payment collected.</small></p></aside></div>':'<div class="box empty"><h3>Your bag is empty</h3><button class="strong" data-view="shop">Start shopping</button></div>');}
function placeOrder(){
if(!navigator.onLine)return notify('Reconnect before ordering.');if(blockedCart())return notify('An item or pack size is unavailable or has insufficient stock. Update your bag before ordering.');if(storeMode!=='open')return notify('The store is not accepting orders.');
const d=deliveryQuote();if(!d.eligible)return notify(d.reason);try{RetailRules.contact(customerPin||{});}catch(err){return notify('Add recipient name and phone using Choose delivery location.');}const list=entries();if(!list.length)return;

const q=pricing();if(reviewedCheckout!==JSON.stringify({q,d,policy})){checkout();return notify('Your offer or delivery quote changed. Review the updated total, then place the order again.');}
// The backend must repeat this calculation under a transaction at real checkout.
try{InventoryRules.consume(products,cart,categoryVisible);}catch(err){return notify(err.message);}const order={id:'RM-'+(1043+orders.length-1),total:q.total/100,status:'Preparing',items:list.map(e=>e.p.name+(e.size?' ('+e.size+')':'')+' × '+e.qty).join(' · '),driver:'Unassigned',refund:'None',createdAt:new Date().toISOString(),policy:{...policy},brandSnapshot:branding.name,businessSnapshot:{name:branding.name,address:branding.address,phone:branding.phone,email:branding.email},pricingSnapshot:q,offerSnapshot:JSON.parse(JSON.stringify(billOffer)),deliverySnapshot:{...d,store:{...storePin},customer:{...customerPin},basis:'straight-line',city:serviceCity},lineItems:q.lines,history:[],notifications:[]};
list.forEach(e=>stockEvent(e.p,{id:e.v.id,label:e.size},-e.qty,'Order '+order.id));orders.unshift(order);StoreRules.event(order,'System','Demo order confirmed. Offers and delivery quote saved.');StoreRules.queueEmail(order,'Order confirmed');cart={};go('orders');notify('Demo order created. Discounted total and delivery details are fixed in its invoice. No charge made.');}

function offerSettings(){return '<div class="columns"><div class="box"><div class="row between"><h3>Bill offer</h3><span class="status">'+scheduleStatus(billOffer)+'</span></div><label><input id="bill-enabled" type="checkbox" '+(billOffer.enabled?'checked':'')+'> Enable bill offer</label><label><span>Customer-facing offer name</span><input id="bill-name" maxlength="70" value="'+esc(billOffer.name)+'"></label><div class="cancel-grid"><label><span>Discount (%)</span><input id="bill-percent" type="number" min="0" max="100" step="0.1" value="'+billOffer.percent+'"></label><label><span>Minimum items total (₹)</span><input id="bill-min" type="number" min="0" value="'+billOffer.minimumPaise/100+'"></label><label><span>Maximum saving (₹) · 0 = uncapped</span><input id="bill-cap" type="number" min="0" value="'+billOffer.capPaise/100+'"></label><label><span>Offer combination</span><select id="bill-stack"><option value="no" '+(!billOffer.stack?'selected':'')+'>Best offer only</option><option value="yes" '+(billOffer.stack?'selected':'')+'>Combine with product offers</option></select></label><label><span>Starts · your device time</span><input id="bill-start" type="datetime-local" value="'+localTime(billOffer.start)+'"></label><label><span>Ends · your device time</span><input id="bill-end" type="datetime-local" value="'+localTime(billOffer.end)+'"></label></div><button class="strong" data-save-bill="1">Save bill offer</button></div><div class="box"><h3>Automatic calculator</h3><label><span>Example basket (₹)</span><input id="offer-example" type="number" min="0" value="1000"></label><div id="offer-example-result" aria-live="polite"></div><p class="muted">Uses saved bill settings, no product discounts or delivery charge.</p><h3>Built-in offer rules</h3><p>Percentage discounts apply to items, never to delivery charges.</p><p>Dates, minimum spend and saving caps are checked at checkout.</p><p>With stacking off, the customer gets the better total discount.</p><p>Paid orders keep their original prices and offers.</p></div></div><div class="row between section"><h3>Product offers</h3><span class="muted">Product percentage applies to all its pack sizes</span></div>'+products.map(p=>'<div class="box section"><div class="row between"><h3>'+esc(p.name)+'</h3><span class="status">'+scheduleStatus(p.discount)+'</span></div><div class="editgrid"><label><span>Discount (%) · 0 = off</span><input id="product-discount-'+p.id+'" type="number" min="0" max="100" step="0.1" value="'+(p.discount?.percent||0)+'"></label><div><small>Lowest option price</small><p>'+money(p.price)+'</p></div><div><small>Offer price preview</small><p id="product-sale-'+p.id+'">'+money(Math.round(p.price*100*(1-(p.discount?.percent||0)/100))/100)+'</p></div></div><div class="cancel-grid"><label><span>Starts · your device time</span><input id="product-start-'+p.id+'" type="datetime-local" value="'+localTime(p.discount?.start)+'"></label><label><span>Ends · your device time</span><input id="product-end-'+p.id+'" type="datetime-local" value="'+localTime(p.discount?.end)+'"></label></div><button data-save-product-offer="'+p.id+'">Save product offer</button></div>').join('');}
function offerExample(){const target=root.querySelector('#offer-example-result');if(!target)return;const raw=Number(root.querySelector('#offer-example').value);if(!Number.isFinite(raw)||raw<0){target.textContent='Enter a positive basket value.';return;}const q=CommerceRules.quote([{pricePaise:Math.round(raw*100),quantity:1}],billOffer);target.innerHTML='<div class="sum"><span>Items total</span><b>'+money(q.subtotal/100)+'</b></div><div class="sum"><span>Bill saving</span><b>'+money(q.billDiscount/100)+'</b></div><div class="sum"><span>After offer</span><b>'+money(q.total/100)+'</b></div>';}
function deliverySettings(){return '<div class="columns"><div class="box"><h3>Delivery charges & limits</h3><label><input id="delivery-enabled" type="checkbox" '+(deliveryEnabled?'checked':'')+'> Accept delivery orders</label><label><span>Service radius (km)</span><input id="radius" type="number" min="0.1" max="50" step="0.1" value="'+radius+'"></label><label><span>First distance free (km)</span><input id="free-km" type="number" min="0" step="0.1" value="'+freeKm+'"></label><label><span>Each additional started km (₹)</span><input id="rate" type="number" min="0" step="1" value="'+rate+'"></label><label><input id="free" type="checkbox" '+(free?'checked':'')+'> Free delivery promotion inside the service area</label><label><span>City / service area name</span><input id="service-city" value="'+esc(serviceCity)+'" placeholder="Enter your city"></label><label><span>Allowed PIN codes · comma separated, blank = radius only</span><input id="allowed-pins" value="'+allowedPincodes.join(', ')+'" placeholder="500001, 500002"></label><button class="strong" data-save-geo="1">Save delivery rules</button></div><div class="box"><h3>Store location & coverage</h3><p>'+esc(storePin?.address||'Your real store location has not been set.')+'</p>'+(storePin?'<small>'+storePin.lat.toFixed(6)+', '+storePin.lng.toFixed(6)+'</small>':'')+'<div class="row section"><button class="strong" data-map-mode="store">Set store pin / coverage</button><button data-demo-map="1">Load sample location</button></div><p>Customer pin must fall within '+radius+' km'+(allowedPincodes.length?' and an allowed PIN code':'')+'.</p><div class="notice">This preview uses straight-line radius and charges. Road routing, city-boundary verification and server-side checks are required before launch.</div><p class="muted">Map tiles load from OpenStreetMap when you open the map. Geolocation is requested only when you choose “Use my location”.</p><h3>Rider navigation</h3><p>New orders save the customer pin. Assigned deliveries include a navigation link.</p></div></div>';}
let locationMap=null,mapLayers=[],mapSelection=null,mapMode='customer',leafletPromise=null;
function clearMap(){if(locationMap){locationMap.remove();locationMap=null;}mapLayers=[];}
function leaflet(){if(window.L)return Promise.resolve(window.L);if(leafletPromise)return leafletPromise;
leafletPromise=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';css.integrity='sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=';css.crossOrigin='';document.head.append(css);const s=document.createElement('script');s.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';s.integrity='sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=';s.crossOrigin='';const timer=setTimeout(()=>reject(Error('Map loading timed out. Use coordinates or try again.')),12000);s.onload=()=>{clearTimeout(timer);resolve(window.L);};s.onerror=()=>{clearTimeout(timer);reject(Error('Map unavailable. Enter coordinates or try again.'));};document.head.append(s);}).catch(err=>{leafletPromise=null;throw err;});return leafletPromise;}
function locationModal(mode='customer'){
clearMap();mapMode=mode;mapSelection=mode==='store'?(storePin?{...storePin}:null):(customerPin?{...customerPin}:null);
const p=mapSelection;
modal('<h2>'+(mode==='store'?'Set store location':'Choose delivery location')+'</h2><p>Tap the map or drag the pin. You can also enter coordinates.</p><div class="row"><button data-geolocate="1">Use my location</button><button data-center-store="1">Show store area</button></div><div id="location-map" role="region" aria-label="Interactive delivery location map"><p>Loading map…</p></div><div class="cancel-grid"><label><span>Latitude</span><input id="map-lat" type="number" step="any" min="-90" max="90" value="'+(p?.lat??'')+'"></label><label><span>Longitude</span><input id="map-lng" type="number" step="any" min="-180" max="180" value="'+(p?.lng??'')+'"></label></div><button data-use-coordinates="1">Update pin from coordinates</button><label><span>'+(mode==='store'?'Store address':'House / flat, street and landmark')+'</span><input id="map-address" value="'+esc(p?.address||'')+'" placeholder="Enter complete address"></label>'+(mode==='customer'?'<div class="cancel-grid"><label><span>Recipient name · demo</span><input id="map-name" maxlength="80" value="'+esc(p?.name||'')+'" placeholder="Sample Customer"></label><label><span>Phone number · demo</span><input id="map-phone" inputmode="tel" maxlength="20" value="'+esc(p?.phone||'')+'" placeholder="Use sample details only"></label></div><label><span>PIN code</span><input id="map-pincode" inputmode="numeric" maxlength="6" value="'+esc(p?.pincode||'')+'" placeholder="6-digit PIN code"></label>':'')+'<div id="map-result" class="notice" aria-live="polite"></div><button class="strong" data-save-location="1">Confirm '+(mode==='store'?'store':'delivery')+' location</button><p><small>Location is saved only in this browser preview. Map tiles may be unavailable; coordinate entry still works. The circle shows straight-line coverage.</small></p>');
updateMapResult();const element=root.querySelector('#location-map');
leaflet().then(L=>{if(!element.isConnected||dialog.hidden)return;const center=p||storePin||{lat:22.5,lng:79};locationMap=L.map(element).setView([center.lat,center.lng],p||storePin?13:5);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(locationMap).on('tileerror',()=>{const r=root.querySelector('#map-result');if(r)r.textContent='Map tiles could not load. Use coordinates or your device location.';});locationMap.on('click',e=>selectPoint(e.latlng.lat,e.latlng.lng));drawPins();}).catch(err=>{if(element.isConnected){element.innerHTML='<p>'+esc(err.message)+'</p>';}});
}
function selectPoint(lat,lng){if(!CommerceRules.point({lat,lng}))throw Error('Coordinates are outside valid ranges.');mapSelection={...(mapSelection||{}),lat,lng};root.querySelector('#map-lat').value=lat.toFixed(6);root.querySelector('#map-lng').value=lng.toFixed(6);drawPins();updateMapResult();}
function drawPins(){if(!locationMap||!window.L)return;for(const layer of mapLayers)locationMap.removeLayer(layer);mapLayers=[];const L=window.L,origin=mapMode==='store'?mapSelection:storePin;
if(origin){mapLayers.push(L.circle([origin.lat,origin.lng],{radius:radius*1000,color:'#176340',fillOpacity:0.08,weight:2}).addTo(locationMap));if(mapMode==='customer')mapLayers.push(L.circleMarker([origin.lat,origin.lng],{radius:8,color:'#176340',fillOpacity:1}).addTo(locationMap).bindPopup('Store'));}
if(mapSelection){const m=L.marker([mapSelection.lat,mapSelection.lng],{draggable:true}).addTo(locationMap);m.on('dragend',()=>{const p=m.getLatLng();selectPoint(p.lat,p.lng);});mapLayers.push(m);}
}
function updateMapResult(){const r=root.querySelector('#map-result');if(!r)return;if(mapMode==='store'){r.textContent=mapSelection?'Store pin selected. Green circle: '+radius+' km radius.':'Choose the real store location. No location is assumed.';return;}const p=mapSelection?{...mapSelection,pincode:root.querySelector('#map-pincode')?.value.trim()}:null;const d=CommerceRules.delivery(deliveryConfig(),p);r.textContent=d.reason+(Number.isFinite(d.distance)?' · '+d.distance.toFixed(2)+' km straight line':'')+(d.eligible?' · Delivery '+money(d.feePaise/100):'');}
function delivery(){const assigned=orders.filter(o=>o.driver!=='Unassigned');screen.innerHTML='<span class="eyebrow">Delivery workspace</span><h2>Assigned deliveries</h2><p class="muted">Demo staff view. Real accounts will be restricted to their own assignments.</p>'+(assigned.length?assigned.map(o=>{const p=o.deliverySnapshot?.customer;return '<div class="box section"><div class="row between"><h3>'+o.id+'</h3><span class="status">'+esc(o.status)+'</span></div><p>'+esc(o.driver)+' · '+esc(p?.address||'No location saved for this older sample order')+'</p><p>'+esc(o.items)+'</p><div class="row">'+(p?'<a class="route-link" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.lat+','+p.lng)+'&travelmode=driving">Open driving directions ↗</a>':'')+'<button data-delivered="'+o.id+'">Mark delivered · demo</button><button data-failed="'+o.id+'">Report failed delivery</button></div></div>';}).join(''):'<div class="box empty"><h3>No assigned deliveries</h3><button data-section="orders">Assign rider to an order</button></div>');}
root.addEventListener('input',e=>{if(e.target.id==='offer-example')offerExample();if(e.target.id.startsWith('product-discount-')){const id=Number(e.target.id.replace('product-discount-','')),p=products.find(p=>p.id===id),value=Number(e.target.value),target=root.querySelector('#product-sale-'+id);if(target)target.textContent=Number.isFinite(value)&&value>=0&&value<=100?money(Math.round(p.price*100*(1-value/100))/100):'Use 0–100%';}if(e.target.id==='map-pincode')updateMapResult();});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;try{
if(d.saveBill){const name=root.querySelector('#bill-name').value.trim(),percent=+root.querySelector('#bill-percent').value,minimum=+root.querySelector('#bill-min').value,cap=+root.querySelector('#bill-cap').value,start=scheduleValue('bill-start'),end=scheduleValue('bill-end');validDates(start,end);if(!name||!Number.isFinite(percent)||percent<0||percent>100||!Number.isFinite(minimum)||minimum<0||!Number.isFinite(cap)||cap<0)throw Error('Enter a name, 0–100% discount and non-negative limits.');billOffer={name,enabled:root.querySelector('#bill-enabled').checked,percent,minimumPaise:Math.round(minimum*100),capPaise:Math.round(cap*100),stack:root.querySelector('#bill-stack').value==='yes',start,end};render();notify('Bill offer saved. Existing orders keep their original totals.');}
if(d.saveProductOffer){const id=+d.saveProductOffer,p=products.find(p=>p.id===id),percent=+root.querySelector('#product-discount-'+id).value,start=scheduleValue('product-start-'+id),end=scheduleValue('product-end-'+id);validDates(start,end);if(!Number.isFinite(percent)||percent<0||percent>100)throw Error('Product discount must be between 0 and 100%.');p.discount={enabled:percent>0,percent,start,end};render();notify('Product offer saved; sale price recalculated.');}
if(d.saveGeo){const r=+root.querySelector('#radius').value,f=+root.querySelector('#free-km').value,t=+root.querySelector('#rate').value,pins=root.querySelector('#allowed-pins').value.split(',').map(s=>s.trim()).filter(Boolean);if(!Number.isFinite(r)||r<=0||r>50||!Number.isFinite(f)||f<0||f>r||!Number.isFinite(t)||t<0||pins.some(p=>!/^\d{6}$/.test(p)))throw Error('Use a radius up to 50 km, a free distance within that radius, non-negative charges and 6-digit PIN codes.');radius=r;freeKm=f;rate=t;free=root.querySelector('#free').checked;deliveryEnabled=root.querySelector('#delivery-enabled').checked;serviceCity=root.querySelector('#service-city').value.trim();allowedPincodes=[...new Set(pins)];render();notify('Delivery rules saved. Checkout will recheck customer eligibility.');}
if(d.mapMode)locationModal(d.mapMode);
if(d.demoMap){storePin={lat:17.385,lng:78.4867,address:'SAMPLE ONLY · Hyderabad reference point'};serviceCity='Hyderabad · sample only';customerPin=null;render();notify('Sample location loaded for testing. Replace it with your actual store before launch.');}
if(d.useCoordinates){const la=root.querySelector('#map-lat').value,lo=root.querySelector('#map-lng').value;if(!la||!lo)throw Error('Enter both latitude and longitude.');selectPoint(+la,+lo);locationMap?.setView([+la,+lo],14);}
if(d.centerStore){if(!storePin)throw Error('Set the store pin first or load the sample location in Admin → Delivery.');locationMap?.setView([storePin.lat,storePin.lng],13);}
if(d.geolocate){if(!navigator.geolocation)throw Error('Device location is unavailable. Choose a pin or coordinates.');const button=b;button.disabled=true;navigator.geolocation.getCurrentPosition(pos=>{button.disabled=false;if(!root.querySelector('#map-lat')||dialog.hidden)return;selectPoint(pos.coords.latitude,pos.coords.longitude);locationMap?.setView([pos.coords.latitude,pos.coords.longitude],15);notify('Device location selected. Check the pin and address before confirming.');},()=>{button.disabled=false;notify('Location permission denied or unavailable. Tap the map or enter coordinates.');},{enableHighAccuracy:true,timeout:10000,maximumAge:60000});}
if(d.saveLocation){if(!CommerceRules.point(mapSelection))throw Error('Select a valid location first.');const address=root.querySelector('#map-address').value.trim();if(address.length<5)throw Error('Enter a complete address or landmark.');const selected={...mapSelection,address};if(mapMode==='customer'){Object.assign(selected,RetailRules.contact({name:root.querySelector('#map-name').value,phone:root.querySelector('#map-phone').value}));selected.pincode=root.querySelector('#map-pincode').value.trim();if(!/^\d{6}$/.test(selected.pincode))throw Error('Enter a 6-digit PIN code.');customerPin=selected;}else{storePin=selected;customerPin=null;}clearMap();dialog.hidden=true;render();notify(mapMode==='store'?'Store pin saved. Customers must reconfirm their delivery pin.':'Delivery location saved. Eligibility is shown in your bag.');}
}catch(err){notify(err.message);}queueMicrotask(saveState);});

function activeNotice(){return ContentRules.notice(serviceNotice);}
function syncBrand(){document.title=branding.name+' · Store Preview';const logo=branding.logo?'<img class="store-logo" alt="" src="'+esc(branding.logo)+'">':'';root.querySelector('header .brand').innerHTML=logo+'<div>'+esc(branding.name)+'<div class="brand-tagline">'+esc(branding.tagline)+'</div></div>';root.querySelector('footer .brand').textContent=branding.name;const tagline=root.querySelector('#preview-tagline');if(tagline)tagline.textContent=branding.tagline;let notice=root.querySelector('#service-notice');if(!notice){notice=document.createElement('div');notice.id='service-notice';root.querySelector('header').after(notice);}notice.hidden=!activeNotice();notice.innerHTML=activeNotice()?'<b>'+esc(serviceNotice.reason)+'</b><span>'+esc(serviceNotice.message)+(serviceNotice.extraMinutes?' · Estimated extra wait: '+serviceNotice.extraMinutes+' minutes':'')+(serviceNotice.pauseOrders?' · New delivery orders paused':'')+'</span>':'';}
function categoryVisible(name){return categories.some(c=>c.name===name&&c.enabled);}
function blockedCart(){return entries().some(e=>!!e.issue||!categoryVisible(e.p.cat));}
function stopSlides(){if(slideTimer){clearInterval(slideTimer);slideTimer=null;}}
function liveSlides(){return slides.filter(s=>s.enabled&&(!s.target||categoryVisible(s.target)));}
function slideView(){const list=liveSlides();if(!list.length)return '';slideIndex=((slideIndex%list.length)+list.length)%list.length;const s=list[slideIndex];return '<section class="offer-carousel" aria-label="Store promotions" aria-roledescription="carousel"><div class="slide-copy"><span class="eyebrow">From your local store</span><h2>'+esc(s.title)+'</h2><p>'+esc(s.body)+'</p><button class="strong" data-slide-category="'+esc(s.target||'All')+'">'+esc(s.button||'Shop now')+' →</button></div>'+(s.image?'<div class="slide-image"><img alt="'+esc(s.title)+'" src="'+esc(s.image)+'" loading="lazy"></div>':'<div class="slide-decoration" aria-hidden="true">'+(s.target==='Homemade Food'?'🍲':s.target==='Snacks'?'🥨':'🛍️')+'</div>')+'<div class="slide-controls"><button data-slide-step="-1" aria-label="Previous promotion">←</button><span aria-live="off">'+(slideIndex+1)+' / '+list.length+'</span><button data-slide-step="1" aria-label="Next promotion">→</button><button data-slide-pause="1">'+(slidePaused?'Play slideshow':'Pause slideshow')+'</button></div></section>';}
function paintSlide(){const area=root.querySelector('#slideshow');if(area)area.innerHTML=slideView();}
function startSlides(){stopSlides();if(slidePaused||liveSlides().length<2||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;slideTimer=setInterval(()=>{if(view!=='shop'||document.hidden||!dialog.hidden)return;const area=root.querySelector('#slideshow');if(!area||area.matches(':hover')||area.contains(document.activeElement))return;slideIndex++;paintSlide();},7000);}
function videoCards(){const enabled=videos.filter(v=>v.enabled);if(!enabled.length)return '';return '<section class="section"><div class="row between"><h2>From our store</h2><small>Videos & promotions</small></div><div class="video-grid">'+enabled.map(v=>'<article class="box"><div id="video-slot-'+v.id+'" class="video-slot"><span class="eyebrow">'+esc(ContentRules.video(v.url).provider)+' video</span><h3>'+esc(v.title)+'</h3><button class="strong" data-play-video="'+v.id+'">▶ Play video</button><small>Loads the video provider when played</small></div><p>'+esc(v.caption)+'</p><a target="_blank" rel="noopener noreferrer" href="'+esc(ContentRules.video(v.url).original)+'">Open video on '+esc(ContentRules.video(v.url).provider)+' ↗</a></article>').join('')+'</div></section>';}
function decorateShop(){if(storeMode!=='open')return;const hero=screen.querySelector('.hero');if(hero){hero.querySelector('p').textContent=branding.description;const region=document.createElement('div');region.id='slideshow';hero.after(region);paintSlide();}screen.insertAdjacentHTML('beforeend',videoCards());startSlides();}
function contentSettings(){return '<nav class="subnav"><button data-content-tab="brand" class="'+(contentTab==='brand'?'active':'')+'">Brand & contact</button><button data-content-tab="slides" class="'+(contentTab==='slides'?'active':'')+'">Offer slideshow</button><button data-content-tab="videos" class="'+(contentTab==='videos'?'active':'')+'">Videos</button><button data-content-tab="categories" class="'+(contentTab==='categories'?'active':'')+'">Categories</button></nav><div id="content-settings">'+(contentTab==='brand'?brandForm():contentTab==='slides'?slidesForm():contentTab==='videos'?videosForm():categoriesForm())+'</div>';}
function brandForm(){return '<div class="columns"><div class="box"><h3>Make it your store</h3><label><span>App / store name</span><input id="brand-name" maxlength="60" value="'+esc(branding.name)+'"></label><label><span>Tagline</span><input id="brand-tagline" maxlength="110" value="'+esc(branding.tagline)+'"></label><label><span>Homepage description</span><textarea id="brand-description" maxlength="250">'+esc(branding.description)+'</textarea></label><label><span>Logo image · HTTPS URL or upload below</span><input id="brand-logo" type="text" value="'+esc(branding.logo)+'"></label><label><span>Upload logo · PNG/JPEG/WebP, up to 600 KB</span><input type="file" accept="image/png,image/jpeg,image/webp" data-image-field="brand-logo"></label><button class="strong" data-save-brand="1">Save brand & contact</button></div><div class="box"><h3>Contact & about</h3><label><span>Phone</span><input id="brand-phone" maxlength="25" value="'+esc(branding.phone)+'"></label><label><span>Email</span><input id="brand-email" type="email" value="'+esc(branding.email)+'"></label><label><span>Public address</span><textarea id="brand-address">'+esc(branding.address)+'</textarea></label><label><span>Opening hours</span><input id="brand-hours" value="'+esc(branding.hours)+'"></label><label><span>About the store</span><textarea id="brand-about">'+esc(branding.about)+'</textarea></label><small>Changing the store name updates this app’s header and page title. It does not rename the domain or an installed app automatically.</small></div></div>';}
function slidesForm(){return '<div class="row between"><h3>Homepage promotions</h3><button class="strong" data-add-slide="1">+ Add slide</button></div><p class="muted">Slides are advertisements. Set actual discounts under Offers. Image uploads are retained only in this browser preview.</p><div class="row"><label><input id="slides-autoplay" type="checkbox" '+(!slidePaused?'checked':'')+'> Rotate every 7 seconds</label><button data-save-slides="1">Save rotation</button></div>'+slides.map((s,i)=>'<div class="box section"><div class="row between"><h3>'+esc(s.title)+'</h3><span class="status">'+(s.enabled?'Visible':'Hidden')+'</span></div><div class="row"><button data-edit-slide="'+s.id+'">Edit</button><button data-toggle-slide="'+s.id+'">'+(s.enabled?'Hide':'Show')+'</button><button data-move-slide="'+s.id+'" data-direction="-1" '+(!i?'disabled':'')+'>Move up</button><button data-move-slide="'+s.id+'" data-direction="1" '+(i===slides.length-1?'disabled':'')+'>Move down</button><button data-delete-slide="'+s.id+'">Remove</button></div></div>').join('');}
function slideEditor(s){modal('<h2>'+esc(s?'Edit promotion':'New promotion')+'</h2><label><span>Title</span><input id="slide-title" maxlength="90" value="'+esc(s?.title||'')+'"></label><label><span>Description</span><textarea id="slide-body" maxlength="240">'+esc(s?.body||'')+'</textarea></label><label><span>Image URL · HTTPS or uploaded image</span><input id="slide-image" value="'+esc(s?.image||'')+'"></label><label><span>Upload image · PNG/JPEG/WebP, up to 600 KB</span><input type="file" accept="image/png,image/jpeg,image/webp" data-image-field="slide-image"></label><div class="cancel-grid"><label><span>Button text</span><input id="slide-button" maxlength="30" value="'+esc(s?.button||'Explore')+'"></label><label><span>Open category</span><select id="slide-target"><option value="">All products</option>'+categories.map(c=>'<option '+(s?.target===c.name?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label></div><button class="strong" data-save-slide="'+(s?.id||'new')+'">Save slide</button>');}
function videosForm(){return '<div class="row between"><h3>Promotional videos</h3><button class="strong" data-add-video="1">+ Add video</button></div><p>Paste a YouTube or Vimeo video link. No embed code is required.</p><p class="muted">The video owner must allow embedding. Domain restrictions, private videos or removed videos may block playback.</p>'+(videos.length?videos.map(v=>'<div class="box section"><h3>'+esc(v.title)+'</h3><p>'+esc(ContentRules.video(v.url).provider)+' · '+(v.enabled?'Visible':'Hidden')+'</p><div class="row"><button data-edit-video="'+v.id+'">Edit</button><button data-toggle-video="'+v.id+'">'+(v.enabled?'Hide':'Show')+'</button><button data-delete-video="'+v.id+'">Remove</button></div></div>').join(''):'<div class="box empty">No videos yet. Add your own shop, product or offer video.</div>');}
function videoEditor(v){modal('<h2>'+esc(v?'Edit video':'Add a video')+'</h2><label><span>Video title</span><input id="video-title" maxlength="90" value="'+esc(v?.title||'')+'"></label><label><span>YouTube / Vimeo link</span><input id="video-url" type="url" value="'+esc(v?.url||'')+'" placeholder="https://www.youtube.com/watch?v=…"></label><label><span>Caption / offer details</span><textarea id="video-caption" maxlength="240">'+esc(v?.caption||'')+'</textarea></label><button class="strong" data-save-video="'+(v?.id||'new')+'">Save video</button><p><small>Only supported video URLs are accepted. Playback loads after the viewer presses Play.</small></p>');}
function categoriesForm(){return '<div class="row between"><h3>Product categories</h3><button class="strong" data-add-category="1">+ Add category</button></div><p class="muted">Renaming updates its products and slide links. Hiding a category also stops its products from being ordered.</p>'+categories.map((c,i)=>'<div class="listrow"><div class="grow"><b>'+esc(c.name)+'</b><br><small>'+products.filter(p=>p.cat===c.name).length+' products · '+(c.enabled?'Visible':'Hidden')+'</small></div><button data-edit-category="'+i+'">Rename</button><button data-toggle-category="'+i+'">'+(c.enabled?'Hide':'Show')+'</button></div>').join('')+'<div class="notice">Snacks, Food and Homemade Food are included. Food products need appropriate ingredients, allergen, storage and preparation details before sale; these demo categories are not a food-business approval.</div>';}
function delaySettings(){return '<div class="columns"><div class="box"><h3>Delivery service notice</h3><label><input id="notice-enabled" type="checkbox" '+(serviceNotice.enabled?'checked':'')+'> Show a customer notice</label><label><span>Reason</span><select id="notice-reason">'+['Weather delay','Heavy demand','Road disruption','Delivery staff unavailable','Other service update'].map(s=>'<option '+(s===serviceNotice.reason?'selected':'')+'>'+s+'</option>').join('')+'</select></label><label><span>Customer message</span><textarea id="notice-message" maxlength="300">'+esc(serviceNotice.message)+'</textarea></label><label><span>Estimated additional minutes · 0 = no estimate</span><input id="notice-minutes" type="number" min="0" max="1440" value="'+serviceNotice.extraMinutes+'"></label><label><span>Automatically expire notice · your device time</span><input id="notice-expiry" type="datetime-local" value="'+localTime(serviceNotice.expiresAt)+'"></label><label><input id="notice-pause" type="checkbox" '+(serviceNotice.pauseOrders?'checked':'')+'> Pause new delivery orders while this notice is active</label><button class="strong" data-save-notice="1">Publish notice</button> <button data-clear-notice="1">Clear notice</button></div><div class="box"><h3>Customers stay informed</h3><p>The notice appears throughout the app and at checkout.</p><p>Publishing records an update on active orders and creates preview email notifications.</p><p>Orders keep their existing statuses. A weather delay does not mark an order delivered or cancelled.</p><p>Existing order tracking remains available while new deliveries are paused.</p><div class="notice">Manual admin control. No automatic weather feed is connected. Email notifications are recorded, not sent.</div></div></div>';}
function publishNotice(next){serviceNotice=next;const on=activeNotice(),text=on?next.reason+': '+next.message+(next.extraMinutes?' Estimated additional wait '+next.extraMinutes+' minutes.':''):'The service-delay notice has been cleared.';for(const o of orders.filter(o=>!['Delivered','Cancelled'].includes(o.status))){StoreRules.event(o,'Admin',text);StoreRules.queueEmail(o,on?'Delivery service update':'Delivery notice cleared');}render();notify('Service notice updated. Active-order timelines and preview email records updated.');}
root.addEventListener('change',async e=>{const target=e.target.dataset.imageField;if(!target)return;const file=e.target.files?.[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>600*1024)throw Error('Choose PNG, JPEG or WebP up to 600 KB.');const field=root.querySelector('#'+target);const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read the image.'));r.readAsDataURL(file);});if(field.isConnected){field.value=ContentRules.image(data);notify('Image loaded. Save this form to apply it.');}}catch(err){notify(err.message);}});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;try{
if(d.contentTab){contentTab=d.contentTab;admin();}
if(d.saveBrand){const name=root.querySelector('#brand-name').value.trim(),email=root.querySelector('#brand-email').value.trim();if(!name)throw Error('Enter your store name.');if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Enter a valid contact email.');branding={name,tagline:root.querySelector('#brand-tagline').value.trim(),description:root.querySelector('#brand-description').value.trim(),logo:ContentRules.image(root.querySelector('#brand-logo').value.trim()),phone:root.querySelector('#brand-phone').value.trim(),email,address:root.querySelector('#brand-address').value.trim(),hours:root.querySelector('#brand-hours').value.trim(),about:root.querySelector('#brand-about').value.trim()};render();notify('Store branding and contact details updated in this browser.');}
if(d.addSlide)slideEditor(null);if(d.editSlide)slideEditor(slides.find(s=>s.id===d.editSlide));
if(d.saveSlide){const title=root.querySelector('#slide-title').value.trim();if(!title)throw Error('Enter a slide title.');const values={title,body:root.querySelector('#slide-body').value.trim(),image:ContentRules.image(root.querySelector('#slide-image').value.trim()),button:root.querySelector('#slide-button').value.trim()||'Explore',target:root.querySelector('#slide-target').value};if(d.saveSlide==='new')slides.push({id:'slide-'+Date.now(),enabled:true,...values});else Object.assign(slides.find(s=>s.id===d.saveSlide),values);dialog.hidden=true;render();notify('Promotion slide saved. Product pricing has not changed.');}
if(d.toggleSlide){const s=slides.find(s=>s.id===d.toggleSlide);s.enabled=!s.enabled;render();}
if(d.moveSlide){const i=slides.findIndex(s=>s.id===d.moveSlide),j=i+Number(d.direction);if(j>=0&&j<slides.length)[slides[i],slides[j]]=[slides[j],slides[i]];render();}
if(d.deleteSlide){slides=slides.filter(s=>s.id!==d.deleteSlide);render();}
if(d.saveSlides){slidePaused=!root.querySelector('#slides-autoplay').checked;notify('Slideshow rotation preference saved.');}
if(d.slideStep){slideIndex+=Number(d.slideStep);paintSlide();}
if(d.slidePause){slidePaused=!slidePaused;paintSlide();startSlides();}
if(d.slideCategory){category=d.slideCategory;shop();screen.querySelector('#search')?.focus();}
if(d.addVideo)videoEditor(null);if(d.editVideo)videoEditor(videos.find(v=>v.id===d.editVideo));
if(d.saveVideo){const title=root.querySelector('#video-title').value.trim(),url=root.querySelector('#video-url').value.trim();if(!title)throw Error('Enter a video title.');ContentRules.video(url);const values={title,url,caption:root.querySelector('#video-caption').value.trim()};if(d.saveVideo==='new')videos.push({id:'video-'+Date.now(),enabled:true,...values});else Object.assign(videos.find(v=>v.id===d.saveVideo),values);dialog.hidden=true;render();notify('Video saved. Preview playback on the Shop page.');}
if(d.toggleVideo){const v=videos.find(v=>v.id===d.toggleVideo);v.enabled=!v.enabled;render();}if(d.deleteVideo){videos=videos.filter(v=>v.id!==d.deleteVideo);render();}
if(d.playVideo){const v=videos.find(v=>v.id===d.playVideo),parsed=ContentRules.video(v.url),slot=root.querySelector('#video-slot-'+v.id);slot.innerHTML='<iframe title="'+esc(v.title)+'" src="'+esc(parsed.embed+'&autoplay=1')+'" allow="autoplay; encrypted-media; fullscreen; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>';}
if(d.addCategory!==undefined||d.editCategory!==undefined){const i=d.editCategory!==undefined?Number(d.editCategory):-1;modal('<h2>'+ (i<0?'Add category':'Rename category')+'</h2><label><span>Category name</span><input id="category-name" maxlength="40" value="'+esc(i<0?'':categories[i].name)+'"></label><button class="strong" data-save-category="'+i+'">Save category</button>');}
if(d.saveCategory!==undefined){const i=Number(d.saveCategory),old=i>=0?categories[i].name:'',name=ContentRules.categoryName(root.querySelector('#category-name').value,categories.map(c=>c.name),old);if(i<0)categories.push({name,enabled:true});else{categories[i].name=name;products.forEach(p=>{if(p.cat===old)p.cat=name;});slides.forEach(s=>{if(s.target===old)s.target=name;});if(category===old)category=name;}dialog.hidden=true;render();notify('Category saved.');}
if(d.toggleCategory!==undefined){const c=categories[Number(d.toggleCategory)];c.enabled=!c.enabled;if(category===c.name&&!c.enabled)category='All';render();notify(c.enabled?'Category is visible.':'Category hidden; its products cannot be ordered.');}
if(d.saveNotice){const message=root.querySelector('#notice-message').value.trim(),minutes=Number(root.querySelector('#notice-minutes').value),expiry=scheduleValue('notice-expiry');if(!message||!Number.isInteger(minutes)||minutes<0||minutes>1440)throw Error('Enter a message and an estimate between 0 and 1440 whole minutes.');if(expiry&&Date.parse(expiry)<=Date.now())throw Error('Choose a future expiry time or leave it blank.');publishNotice({enabled:root.querySelector('#notice-enabled').checked,reason:root.querySelector('#notice-reason').value,message,extraMinutes:minutes,pauseOrders:root.querySelector('#notice-pause').checked,expiresAt:expiry});}
if(d.clearNotice)publishNotice({...serviceNotice,enabled:false,pauseOrders:false});
}catch(err){notify(err.message);}queueMicrotask(saveState);});

let selectedVariants={},variantDraft=null;
function chosenVariant(p){return p.variants.find(v=>v.id===selectedVariants[p.id]&&v.enabled)||p.variants.find(v=>v.enabled&&v.stock>0)||p.variants.find(v=>v.enabled)||p.variants[0];}
function safeProductImage(raw){if(!raw)return '';try{return ContentRules.image(raw);}catch{return '';}}
function productGrid(){screen.querySelector('#products').innerHTML=products.filter(p=>categoryVisible(p.cat)&&(category==='All'||category===p.cat)&&p.name.toLowerCase().includes(query.toLowerCase())).map(p=>{const v=chosenVariant(p),img=safeProductImage(p.image),canAdd=p.kind!=='ebook'&&v.enabled&&v.stock>0;return '<article class="product"><div class="picture">'+(img?'<img alt="'+esc(p.name)+'" src="'+esc(img)+'" loading="lazy">':esc(p.emoji))+'<span class="tag">'+esc(p.offer)+'</span></div><small>'+esc(p.cat)+'</small><h3>'+esc(p.name)+'</h3><small>'+esc(p.unit)+'</small><label><span>Choose pack / size</span><select id="variant-'+p.id+'" data-choose-variant="'+p.id+'" aria-label="Pack size for '+esc(p.name)+'">'+p.variants.filter(v=>v.enabled).map(o=>'<option value="'+esc(o.id)+'" '+(o.id===v.id?'selected':'')+'>'+esc(o.label)+' — '+money(o.price)+(o.stock?'':' · Sold out')+'</option>').join('')+'</select></label>'+(p.foodNotes?'<button data-food-details="'+p.id+'">Food details</button>':'')+'<div class="row between"><div>'+variantPrice(p,v)+'<small class="stock-note">'+(canAdd?v.stock+' packs available':'This option is unavailable')+'</small></div><button class="'+(canAdd?'strong':'')+'" data-add="'+p.id+'" '+(!canAdd?'disabled':'')+'>'+(canAdd?'+ Add':p.kind==='ebook'?'Connected setup needed':'Sold out')+'</button></div></article>';}).join('')||'<p>No products found.</p>';}
function variantPrice(p,v){const q=CommerceRules.quote([{pricePaise:Math.round(v.price*100),quantity:1,offer:p.discount}],{});return '<span class="price">'+money(q.total/100)+'</span>'+(q.savings?' <del class="muted">'+money(v.price)+'</del>':'');}
function editProduct(p){variantDraft={productId:p.id,rows:p.variants.map(v=>({...v}))};modal('<h2>Edit '+esc(p.name)+'</h2><label><span>Product name</span><input id="edit-name" maxlength="120" value="'+esc(p.name)+'"></label><div class="cancel-grid"><label><span>Category</span><select id="edit-category">'+categories.map(c=>'<option '+(c.name===p.cat?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><label><span>Description / pack note</span><input id="edit-unit" maxlength="150" value="'+esc(p.unit)+'"></label></div><label><span>Ingredients, allergens, preparation and storage notes</span><textarea id="edit-food" maxlength="2000">'+esc(p.foodNotes||'')+'</textarea></label><label><span>Offer label</span><input id="edit-offer" maxlength="60" value="'+esc(p.offer)+'"></label><div class="row between section"><h3>Pack sizes & inventory</h3><button data-add-variant="1">+ Add option</button></div><p class="muted">Each option has its own price and stock, counted as packs. Disable an option to stop selling it. Past invoices retain its original label and price.</p><div id="variant-editor"></div><label><span>Product image · PNG/JPEG/WebP, up to 600 KB</span><input id="edit-image" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="row"><button class="strong" data-save-product="'+p.id+'">Save product & options</button><button data-act="close">Discard changes</button></div>');drawVariantEditor();}
function drawVariantEditor(){const area=root.querySelector('#variant-editor');if(!area||!variantDraft)return;area.innerHTML=variantDraft.rows.map((v,i)=>'<div class="variant-edit-row"><label><span>Label (e.g. 250 g / Blue · L)</span><input data-variant-field="label" data-index="'+i+'" maxlength="60" value="'+esc(v.label)+'"></label><label><span>Price per pack (₹)</span><input data-variant-field="price" data-index="'+i+'" type="number" min="0.01" max="1000000" step="0.01" value="'+v.price+'"></label><label><span>Available packs</span><input data-variant-field="stock" data-index="'+i+'" type="number" min="0" max="1000000" step="1" value="'+v.stock+'"></label><label><input data-variant-field="enabled" data-index="'+i+'" type="checkbox" '+(v.enabled?'checked':'')+'> Sell</label></div>').join('');}
async function saveProduct(p,button){if(!variantDraft||variantDraft.productId!==p.id)return notify('Open the product editor again.');button.disabled=true;try{
const name=root.querySelector('#edit-name').value.trim(),cat=root.querySelector('#edit-category').value,unit=root.querySelector('#edit-unit').value.trim(),foodNotes=root.querySelector('#edit-food').value.trim(),offer=root.querySelector('#edit-offer').value.trim();
if(!name||name.length>120)throw Error('Enter a product name up to 120 characters.');if(!categories.some(c=>c.name===cat))throw Error('Choose a valid category.');
const variants=InventoryRules.validate(variantDraft.rows);let image=p.image;const f=root.querySelector('#edit-image').files[0];
if(f){if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>600*1024)throw Error('Choose a PNG, JPEG or WebP up to 600 KB.');image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Image upload could not be read.'));r.readAsDataURL(f);});image=ContentRules.image(image);}
if(!button.isConnected)throw Error('Editor closed before saving. Reopen the product to try again.');
const beforeVariants=p.variants.map(v=>({...v}));Object.assign(p,{name,cat,unit,foodNotes,offer,variants,image});InventoryRules.sync(p);p.variants.forEach(v=>stockEvent(p,v,v.stock-(beforeVariants.find(old=>old.id===v.id)?.stock||0),'Admin inventory adjustment'));variantDraft=null;dialog.hidden=true;render();notify('Product options saved. Old orders keep their original prices and pack sizes.');
}catch(err){notify(err.message);}finally{button.disabled=false;}}
function variantInventoryPanel(){return '<div class="row between"><h3>Product catalogue</h3><button class="strong" data-act="new">+ Add product</button></div>'+products.map(p=>'<article class="box section"><div class="row between"><div><h3>'+esc(p.name)+'</h3><small>'+esc(p.cat)+' · '+p.stock+' available packs</small></div><button data-edit="'+p.id+'">Edit product & options</button></div><div class="variant-stock-list">'+p.variants.map(v=>'<div class="listrow"><span class="grow">'+esc(v.label)+(v.enabled?'':' · Hidden')+'</span><b>'+money(v.price)+'</b><span class="tag">'+v.stock+' packs</span></div>').join('')+'</div></article>').join('');}
function reviewPanel(){return '<h3>Launch readiness</h3><div class="notice"><b>Preview only — not ready for real orders.</b> The role switcher and browser-local storage are not security controls.</div><div class="columns"><div class="box"><h3>Checked in this version</h3><p>Weight and size variants have independent prices and stock.</p><p>Whole-cart validation happens before any stock is reduced.</p><p>Invalid quantities, prices and duplicate variant labels are rejected.</p><p>Unsafe video URLs are blocked; product image URLs are escaped and restricted.</p><p>Discounts, refund limits, status transitions and resend cooldowns have targeted tests.</p></div><div class="box"><h3>Required before launch</h3><p>Supabase authentication, admin/rider permissions and tested row-level policies.</p><p>Server-owned pricing, atomic stock reservations and payment verification.</p><p>Idempotent refunds, webhook replay protection and email delivery.</p><p>Rate limits, backups, monitoring and cross-device concurrency testing.</p><p>Browser/device testing and an authenticated security scan of your staging environment.</p></div></div><p class="muted">Strix is not installed here. This is a source review with targeted tests, not a penetration-test certification.</p>';}
root.addEventListener('change',e=>{if(e.target.dataset.chooseVariant){const id=Number(e.target.dataset.chooseVariant);selectedVariants[id]=e.target.value;productGrid();root.querySelector('#variant-'+id)?.focus();}if(e.target.dataset.variantField==='enabled'&&variantDraft){variantDraft.rows[Number(e.target.dataset.index)].enabled=e.target.checked;}});
root.addEventListener('input',e=>{const field=e.target.dataset.variantField;if(field&&field!=='enabled'&&variantDraft){variantDraft.rows[Number(e.target.dataset.index)][field]=field==='label'?e.target.value:e.target.value===''?NaN:Number(e.target.value);}});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.addVariant&&variantDraft){if(variantDraft.rows.length>=30)return notify('Maximum 30 options per product.');const id='v-'+crypto.randomUUID();variantDraft.rows.push({id,label:'New option '+(variantDraft.rows.length+1),price:1,stock:0,enabled:true});drawVariantEditor();}});

let reportFrom=RetailRules.day(new Date()),reportTo=RetailRules.day(new Date()),inventoryFilter='all',inventorySearch='',inventoryEvents=[];
const categoryIcons={'Ebooks':'📚','Groceries':'🌾','Pickles':'🫙','Home & plastic':'🧺','Clothing':'👕','Snacks':'🥨','Food':'🍛','Homemade Food':'🍲',...Object.fromEntries(RetailRules.additionalCategories.map(c=>[c.name,c.emoji]))};
function categoryWidgets(){return '<div class="category-widgets">'+[{name:'All',enabled:true},...categories.filter(c=>c.enabled)].map(c=>'<button data-cat="'+esc(c.name)+'" class="category-widget '+(category===c.name?'active':'')+'"><span aria-hidden="true">'+(categoryIcons[c.name]||'🛍️')+'</span><span>'+esc(c.name)+'</span></button>').join('')+'</div>';}
function analytics(){const s=RetailRules.stats(orders,products,{from:reportFrom,to:reportTo});return '<div class="box"><div class="row between"><h3>Sales & order statistics</h3><span class="tag">Demo figures · Asia/Kolkata</span></div><div class="report-controls"><label><span>Orders placed from</span><input id="report-from" type="date" value="'+reportFrom+'"></label><label><span>Through</span><input id="report-to" type="date" value="'+reportTo+'"></label><button data-report-apply="1">Apply dates</button><button data-report-today="1">Today</button><button data-report-all="1">All dates</button></div><small>Grouped by order-placement date in India time. Delivered value is not bank settlement or profit.</small></div><div class="stats"><div class="stat"><small>Orders placed</small><b>'+s.orders+'</b></div><div class="stat"><small>Delivered order value</small><b>'+money(s.deliveredPaise/100)+'</b><small>'+s.deliveredOrders+' delivered orders</small></div><div class="stat"><small>Delivered value after completed refunds</small><b>'+money(s.deliveredNetPaise/100)+'</b></div><div class="stat"><small>Refunds completed · selected orders</small><b>'+money(s.completedRefundPaise/100)+'</b></div><div class="stat"><small>Refunds pending · selected orders</small><b>'+money(s.pendingRefundPaise/100)+'</b></div><div class="stat"><small>Available packs · all stock</small><b>'+s.stockPacks+'</b><small>'+s.soldOut+' options sold out</small></div></div><div class="columns"><div class="box"><h3>Order status breakdown</h3>'+Object.entries(s.counts).map(([status,n])=>'<div class="listrow"><span class="grow">'+esc(status)+'</span><b>'+n+'</b></div>').join('')+(s.orders?'':'<p>No orders in this date range.</p>')+'<button data-section="orders">Manage orders</button></div><div class="box"><h3>Delivered item sales by category</h3>'+Object.entries(s.byCategory).map(([cat,v])=>'<div class="listrow"><div class="grow">'+esc(cat)+'<br><small>'+v.packs+' packs</small></div><b>'+money(v.salesPaise/100)+'</b></div>').join('')+(s.deliveredOrders?'':'<p>No delivered orders in this date range.</p>')+'<small>Category totals exclude delivery charges and show discounted item values before refunds.</small></div></div>';}
function inventoryDashboard(){const s=RetailRules.stats(orders,products),rows=s.stockRows.filter(v=>(!inventorySearch||(v.product+' '+v.label+' '+v.category).toLowerCase().includes(inventorySearch.toLowerCase()))&&(inventoryFilter==='all'||inventoryFilter==='low'&&v.enabled&&v.stock>0&&v.stock<=5||inventoryFilter==='out'&&v.enabled&&v.stock===0||inventoryFilter==='hidden'&&!v.enabled));return '<h3>Inventory by pack / size</h3><div class="stats"><div class="stat"><small>Available packs</small><b>'+s.stockPacks+'</b></div><div class="stat"><small>Stock value at listed selling prices</small><b>'+money(s.stockSellingValuePaise/100)+'</b><small>Not cost or profit</small></div><div class="stat"><small>Sold-out options</small><b>'+s.soldOut+'</b></div></div><div class="row section"><input id="inventory-search" class="search" aria-label="Search inventory" placeholder="Search item, category or pack…" value="'+esc(inventorySearch)+'"><select id="inventory-filter" aria-label="Inventory filter" style="max-width:220px">'+[['all','All options'],['low','Low stock · 1–5 packs'],['out','Sold out'],['hidden','Disabled options']].map(([v,label])=>'<option value="'+v+'" '+(v===inventoryFilter?'selected':'')+'>'+label+'</option>').join('')+'</select><button data-inventory-search="1">Filter</button></div><div class="box">'+rows.map(v=>'<div class="listrow"><div class="grow"><b>'+esc(v.product)+'</b><br><small>'+esc(v.category)+' · '+esc(v.label)+(v.enabled?'':' · Hidden')+'</small></div><b>'+v.stock+' packs</b><span>'+money(v.pricePaise/100)+'</span><button data-edit="'+v.productId+'">Update</button></div>').join('')+(rows.length?'':'<p>No matching inventory.</p>')+'</div><div class="box section"><h3>Recent stock movements</h3>'+inventoryEvents.slice(-20).reverse().map(e=>'<div class="listrow"><div class="grow"><b>'+esc(e.name)+' · '+esc(e.variant)+'</b><br><small>'+esc(e.reason)+' · '+stamp(e.at)+'</small></div><b>'+(e.delta>0?'+':'')+e.delta+' packs</b></div>').join('')+(inventoryEvents.length?'':'<p>Movements will appear after orders and inventory edits in this version.</p>')+'<small>Local preview journal. Durable stock audit requires the backend.</small></div>';}
function stockEvent(p,v,delta,reason){if(!delta)return;inventoryEvents.push({at:new Date().toISOString(),productId:p.id,variantId:v.id,name:p.name,variant:v.label,delta,reason});if(inventoryEvents.length>200)inventoryEvents=inventoryEvents.slice(-200);}
function receiptHtml(r){return '<div class="receipt-paper"><div class="receipt-header"><h2>'+esc(r.business.name)+'</h2>'+(r.business.address?'<p>'+esc(r.business.address)+'</p>':'')+'<p>'+esc([r.business.phone,r.business.email].filter(Boolean).join(' · '))+'</p><b>'+esc(r.duplicate?'DUPLICATE · ':'')+(r.copy==='shop'?'SHOP COPY':'CUSTOMER COPY')+'</b></div><div class="receipt-meta"><div><b>Order / receipt ID</b><br>'+esc(r.orderId)+'</div><div><b>Order date</b><br>'+stamp(r.placedAt)+'</div><div><b>Order status</b><br>'+esc(r.status)+'</div></div>'+(r.customer?'<div class="receipt-address"><b>Deliver to</b><p>'+esc(r.customer.name||'Name not captured on older sample')+'<br>'+esc(r.customer.phone||'')+'<br>'+esc(r.customer.address||'')+' '+esc(r.customer.pincode||'')+'</p></div>':'')+(r.lines?'<div class="receipt-table-wrap"><table class="receipt-table"><thead><tr><th>Item / option</th><th>Qty</th><th>Unit price</th><th>Saving</th><th>Amount</th></tr></thead><tbody>'+r.lines.map(l=>'<tr><td>'+esc(l.name)+'<br><small>'+esc(l.variant)+'</small></td><td>'+l.quantity+'</td><td>'+money(l.unitPricePaise/100)+'</td><td>'+money(l.discountPaise/100)+'</td><td>'+money(l.netPaise/100)+'</td></tr>').join('')+'</tbody></table></div><div class="receipt-totals"><div class="sum"><span>Items before discounts</span><b>'+money(r.subtotalPaise/100)+'</b></div><div class="sum"><span>Total savings</span><b>−'+money(r.savingsPaise/100)+'</b></div><div class="sum"><span>Delivery</span><b>'+money(r.deliveryPaise/100)+'</b></div>':'<p>'+esc(r.legacyItems)+'</p><small>Detailed line pricing was not captured for this older sample.</small><div class="receipt-totals">')+'<div class="sum receipt-grand"><b>Order total</b><b>'+money(r.totalPaise/100)+'</b></div>'+(r.refundPendingPaise?'<div class="sum"><span>Refund pending</span><b>'+money(r.refundPendingPaise/100)+'</b></div>':'')+(r.refundedPaise?'<div class="sum"><span>Refund completed</span><b>'+money(r.refundedPaise/100)+'</b></div>':'')+(r.cancellationFeePaise?'<div class="sum"><span>Cancellation deduction</span><b>'+money(r.cancellationFeePaise/100)+'</b></div>':'')+'</div><div class="receipt-foot"><p>'+esc(r.paymentLabel)+'</p><small>'+esc(r.taxLabel)+'. '+(r.duplicate?'Reissued copy; this does not create another order or payment.':'')+'</small>'+(r.copy==='shop'?'<p>Packed by: __________ &nbsp; Checked by: __________</p>':'<p>Thank you for shopping locally.</p>')+'</div></div>';}
function invoice(o,copy='customer',duplicate=false){try{const r=RetailRules.receipt(o,copy,duplicate);modal('<div class="row section"><button data-receipt-open="'+o.id+'" data-copy="customer">Customer copy</button><button data-receipt-open="'+o.id+'" data-copy="shop">Shop copy</button><button data-receipt-open="'+o.id+'" data-copy="'+copy+'" data-duplicate="yes">Duplicate copy</button><button class="strong" data-print-receipt="'+o.id+'" data-copy="'+copy+'" data-duplicate="'+(duplicate?'yes':'no')+'">Print / save PDF</button></div>'+receiptHtml(r));}catch(err){notify(err.message);}}
function printReceipt(o,copy,duplicate){const r=RetailRules.receipt(o,copy,duplicate);let area=document.getElementById('receipt-print');if(!area){area=document.createElement('section');area.id='receipt-print';document.body.append(area);}area.innerHTML=receiptHtml(r);o.printHistory ||= [];o.printHistory.push({at:new Date().toISOString(),copy,duplicate,actor:view==='admin'?'Admin preview':'Customer preview'});saveState();window.print();}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;try{
if(d.reportApply){const from=root.querySelector('#report-from').value,to=root.querySelector('#report-to').value;if(from&&to&&from>to)throw Error('Choose a valid date range.');reportFrom=from;reportTo=to;admin();}
if(d.reportToday){reportFrom=reportTo=RetailRules.day(new Date());admin();}if(d.reportAll){reportFrom=reportTo='';admin();}
if(d.inventorySearch){inventorySearch=root.querySelector('#inventory-search').value.trim();inventoryFilter=root.querySelector('#inventory-filter').value;admin();}
if(d.receiptOpen)invoice(orders.find(o=>o.id===d.receiptOpen),d.copy,d.duplicate==='yes');
if(d.printReceipt)printReceipt(orders.find(o=>o.id===d.printReceipt),d.copy,d.duplicate==='yes');
}catch(err){notify(err.message);}});

restoreState();
products.forEach(p=>{if(p.hasSizes===undefined)p.hasSizes=p.cat==='Clothing';});
if(contentVersion<2){for(const item of [{name:'Teatime snacks · sample',cat:'Snacks',emoji:'🥨'},{name:'Fresh meal · sample',cat:'Food',emoji:'🍛'},{name:'Homemade meal · sample',cat:'Homemade Food',emoji:'🍲'}])products.push({id:Math.max(...products.map(p=>p.id))+1,...item,unit:'Coming soon · sample listing',price:100,stock:0,offer:'Coming soon',foodNotes:'Sample item. Add actual ingredients, allergens, preparation and storage details before enabling sales.'});contentVersion=2;}
if(contentVersion<3){for(const c of RetailRules.additionalCategories){if(!categories.some(x=>x.name===c.name))categories.push({name:c.name,enabled:true});if(!products.some(p=>p.cat===c.name))products.push({id:Math.max(...products.map(p=>p.id))+1,name:c.product,cat:c.name,emoji:c.emoji,unit:'Coming soon · sample product',offer:'Coming soon',price:c.variants[0][1],stock:0,variants:c.variants.map(([label,price],i)=>({id:'option-'+i,label,price,stock:0,enabled:true}))});}contentVersion=3;}
if(contentVersion<4){if(!categories.some(c=>c.name==='Ebooks'))categories.push({name:'Ebooks',enabled:true});if(!products.some(p=>p.cat==='Ebooks'))products.push({id:Math.max(...products.map(p=>p.id))+1,name:'Your ebook · sample',cat:'Ebooks',kind:'ebook',emoji:'📚',unit:'Private uploads and paid downloads use connected mode',offer:'Digital download',price:100,stock:0});contentVersion=4;}
try{products.forEach(p=>InventoryRules.migrate(p));const migrated=InventoryRules.migrateCart(products,cart);cart=migrated.cart;if(migrated.dropped)notify('Some outdated or invalid bag items were removed. Please review your bag.');}catch(err){screen.innerHTML='<div class="box"><h2>Saved preview data needs attention</h2><p>Reset this local demo to load valid sample products.</p><button data-act="reset">Reset demo</button></div>';notify(err.message);return;}
let noticeWasActive=activeNotice();setInterval(()=>{const isActive=activeNotice();if(isActive!==noticeWasActive){noticeWasActive=isActive;syncBrand();if(view==='cart')checkout();}},15000);


render();
})();
